"window.addEventListener('message', function(event) {
    console.log("ZowieSDK: [JS] Received message", event.data);
    if (!event.data) return;

    if (event.data.type === 'visualAidResize') {
        var height = event.data.height;
        window.webkit.messageHandlers.zowieVisualAid.postMessage({ type: 'resize', height: height });
    } else if (event.data.type === 'visualAidSendMessage') {
        var text = event.data.message || event.data.text || "";
        window.webkit.messageHandlers.zowieVisualAid.postMessage({ type: 'sendMessage', text: text });
    } else if (event.data.type === 'visualAidHide') {
        window.webkit.messageHandlers.zowieVisualAid.postMessage({ type: 'hide' });
    }
});
"
